insert into public.category_service_presets (category_id, name, duration_minutes, price, description, sort_order)
select v.category_id::uuid, v.name, v.duration_minutes, v.price, v.description, v.sort_order
from (values
  -- แฮร์ซาลอน (hair-salon)
  ('2d1bec7e-9be4-42a9-bf55-d7e708d709a7','ตัดผม + สระไดร์',60,350,'ตัดและจัดทรงผมตามสไตล์ที่ต้องการ พร้อมสระและไดร์จัดแต่งทรงให้เรียบร้อยก่อนกลับ',0),
  ('2d1bec7e-9be4-42a9-bf55-d7e708d709a7','สระไดร์ + จัดแต่งทรง',40,250,'สระทำความสะอาดเส้นผมและหนังศีรษะ พร้อมไดร์และจัดแต่งทรงให้ดูเรียบร้อยสวยงาม',1),
  ('2d1bec7e-9be4-42a9-bf55-d7e708d709a7','ทำสีผมทั้งศีรษะ',120,1500,'เปลี่ยนสีผมทั้งศีรษะ เลือกเฉดสีได้ตามต้องการ ลงสีทั่วถึง พร้อมสระและไดร์จัดแต่งทรง',2),
  ('2d1bec7e-9be4-42a9-bf55-d7e708d709a7','ทำไฮไลท์',180,2500,'ฟอกและลงสีเป็นช่อให้ผมดูมีมิติและสว่างขึ้น พร้อมสระและไดร์จัดแต่งทรงโดยช่างผู้ชำนาญ',3),
  ('2d1bec7e-9be4-42a9-bf55-d7e708d709a7','ดัดผม',150,1800,'ดัดผมให้เป็นลอนหรือเพิ่มวอลลุ่มตามทรงที่ต้องการ พร้อมสระและจัดแต่งทรงให้เรียบร้อย',4),
  ('2d1bec7e-9be4-42a9-bf55-d7e708d709a7','ยืดผม / รีบอนดิ้ง',240,2200,'ยืดผมให้ตรงเรียบสลวยอย่างเป็นธรรมชาติด้วยน้ำยาคุณภาพ พร้อมสระและจัดแต่งทรงให้เรียบร้อย',5),
  ('2d1bec7e-9be4-42a9-bf55-d7e708d709a7','ทรีตเมนต์บำรุงผม',50,600,'บำรุงเส้นผมที่แห้งเสียให้นุ่มลื่นและมีสุขภาพดีขึ้นด้วยทรีตเมนต์เข้มข้น พร้อมสระและไดร์',6),
  ('2d1bec7e-9be4-42a9-bf55-d7e708d709a7','เซ็ตผมออกงาน',60,800,'จัดแต่งและเซ็ตทรงผมสำหรับงานสำคัญหรือโอกาสพิเศษให้สวยงามคงทนตลอดทั้งวัน',7),
  -- ร้านนวด (massage)
  ('f58b8861-7219-45dc-9775-c90ce015610f','นวดไทยประยุกต์',60,300,'นวดแบบไทยกดจุดและยืดเส้นทั่วร่างกาย ช่วยคลายกล้ามเนื้อและผ่อนคลายความเมื่อยล้า',0),
  ('f58b8861-7219-45dc-9775-c90ce015610f','นวดน้ำมันอโรมา',90,650,'นวดผ่อนคลายด้วยน้ำมันหอมระเหยกลิ่นอโรมาทั่วร่างกาย ช่วยให้รู้สึกผ่อนคลายและบำรุงผิว',1),
  ('f58b8861-7219-45dc-9775-c90ce015610f','นวดฝ่าเท้า',60,300,'กดจุดสะท้อนบริเวณฝ่าเท้าและน่อง ช่วยกระตุ้นการไหลเวียนและคลายความเมื่อยล้าจากการเดิน',2),
  ('f58b8861-7219-45dc-9775-c90ce015610f','นวดคอบ่าไหล่',30,200,'นวดเน้นเฉพาะจุดบริเวณคอ บ่า และไหล่ ช่วยคลายอาการตึงและปวดจากการนั่งทำงานนาน',3),
  ('f58b8861-7219-45dc-9775-c90ce015610f','นวดศีรษะ',30,200,'นวดผ่อนคลายบริเวณศีรษะ ขมับ และต้นคอ ช่วยลดความตึงเครียดและบรรเทาอาการปวดศีรษะ',4),
  ('f58b8861-7219-45dc-9775-c90ce015610f','นวดประคบสมุนไพร',90,550,'นวดตัวร่วมกับลูกประคบสมุนไพรอุ่น ช่วยคลายกล้ามเนื้อและให้ความอบอุ่นแก่ร่างกาย',5),
  ('f58b8861-7219-45dc-9775-c90ce015610f','ขัดผิวสปา',60,600,'ขัดผิวทั่วร่างกายด้วยสครับเพื่อผลัดเซลล์ผิวเก่า ให้ผิวเนียนนุ่มและกระจ่างใสขึ้น',6),
  ('f58b8861-7219-45dc-9775-c90ce015610f','นวดน้ำมันคนท้อง',60,500,'นวดผ่อนคลายสำหรับคุณแม่ตั้งครรภ์โดยพนักงานชำนาญ เน้นท่าทางที่ปลอดภัยและอ่อนโยน',7)
) as v(category_id, name, duration_minutes, price, description, sort_order)
where not exists (
  select 1 from public.category_service_presets p
  where p.category_id = v.category_id::uuid
    and lower(btrim(p.name)) = lower(btrim(v.name))
);